 for(const button of document.querySelectorAll('.dpad button')){button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);keyState[button.dataset.dir]=true;});for(const ev of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(ev,()=>keyState[button.dataset.dir]=false);}

-function movePlayer(p,keys,delta){let x=0,z=0;if(keyState[keys[0]]||keyState[keys[1]])z-=1;if(keyState[keys[2]]||keyState[keys[3]])z+=1;if(keyState[keys[4]]||keyState[keys[5]])x-=1;if(keyState[keys[6]]||keyState[keys[7]])x+=1;
+function movePlayer(p,keys,delta){let x=0,z=0;if(keyState[keys[0]])z-=1;if(keyState[keys[1]])z+=1;if(keyState[keys[2]])x-=1;if(keyState[keys[3]])x+=1;
   const moving=x!==0||z!==0;if(moving){const length=Math.hypot(x,z);x/=length;z/=length;p.group.position.x+=x*5.2*delta;p.group.position.z+=z*5.2*delta;p.facing=Math.atan2(x,z);p.group.rotation.y=p.facing;p.speed=Math.min(1,p.speed+delta*5);}else p.speed=Math.max(0,p.speed-delta*4);
   const radius=Math.hypot(p.group.position.x,p.group.position.z);if(radius>19.5){p.group.position.x*=19.5/radius;p.group.position.z*=19.5/radius;}
   p.group.position.y=Math.sin(performance.now()*.009+(p===player2?1:0))*.035*p.speed;
 }

